const story = "{\"inkVersion\":21,\"root\":[[[\"done\",{\"#n\":\"g-0\"}],null],\"done\",{\"entrance\":[[\"^荒原的风裹着沙粒，打在残碑上发出细碎的声响。远处乔家的车驾已退成几个黑点，最后消失在灰黄的天际线上。你站在古墓前，脚下的土干裂如龟背，缝隙里渗出丝丝寒意。\",\"\\n\",\"^乔无咎负手立在墓门旁，衣袍被风掀动，语气温和：“诸位道友，乔某先说明白。乔家上次派出的探墓队，曾入此墓探查，却无功而返，连墓门内的机关都未能尽数摸清。此番邀诸位同来，只因这墓门上的血锁需五人血印方能开启，乔某一人之力不足。入墓后，机关与蛊虫凶险难测，所得之物按功分宝，乔某绝不独吞。”他说得客气，目光却在你、沈青萝、贾贵、赵黎身上一一掠过，不亲近，也不疏远。\",\"\\n\",\"^沈青萝站在你身侧，指尖无意识地摩挲着腰间一块玉牌。那玉牌色泽青白，边角已被磨得圆润。她察觉你的目光，并未回避，只低声道：“我师弟沈砚，便是上次探墓队的人。木灵宗与乔家有约，我此来既是相助，也要查他下落。”她说完便住了口，指尖收紧，玉牌被攥进掌心。\",\"\\n\",\"^贾贵笑眯眯地搓着手，胖脸上堆着和气：“乔家主说得在理，按功分宝嘛，贾某最是信服。只是这墓里若真有什么凶险，贾某可要先保命，再谈分宝。”他说着拍了拍腰间的储物囊，又补一句，“不过乔家主既然肯请我们，想必已备好万全之策。”\",\"\\n\",\"^赵黎却捻着袖口，年轻的面容上挂着与年纪不符的从容：“老夫活了这些年，见过不少墓，也见过不少话。乔家主说上次无功而返，那上次探墓队的人，如今何在？”他问得随意，语气却带着一丝玩味。乔无咎神色不变，答道：“有人折在机关里，有人失了音讯。墓中凶险，赵道友既称老夫，当知有些事强求不得。”赵黎似笑非笑，不再追问。\",\"\\n\",\"^你走到墓门前，借着天光细看。那门由青石砌成，门面上刻着繁复的纹路，中央嵌着一枚血锁，锁体锈迹斑斑，却隐隐透出暗红光泽。你伸手轻触锁面，指尖感到一丝微弱的震颤——那气息紊乱不堪，像被人反复动过，却又刻意抹平了痕迹。你收回手，未作声，只将目光移向门缝。门缝里透出一股铁锈与药灰混杂的冷气，带着沉沉的死意。\",\"\\n\",\"^乔无咎已取出匕首，在掌心划了一道，血珠渗出，滴在血锁上。锁面泛起一层暗红，像是饥渴地吞饮。他看向众人：“请。”\",\"\\n\",\"^沈青萝率先抬手，指尖凝出一滴血，落在锁上。她动作利落，却在你看向她时，微微偏了偏头。贾贵啧了一声，划破指腹，血滴上去时他皱了下眉，随即又笑起来。赵黎则不紧不慢地弹出一缕血线，落在锁上时，锁面微微一颤。你最后上前，鲜血沾上锁面的一瞬，那血锁发出一声低沉的嗡鸣，裂纹从中心蔓延开来，像蛛网般爬满整块锁体。\",\"\\n\",\"^一声脆响，血锁裂成两半，坠在门前的沙土里。墓门无声地敞开一道缝，冷气扑面而来，带着铁锈的腥味。门内漆黑一片，深处却有一盏尸灯幽幽亮起，昏黄的光摇晃着，映出墓道两侧斑驳的石壁。\",\"\\n\",\"^乔无咎率先迈步，声音平静：“入墓后，诸位跟紧乔某。机关在前，莫要乱碰。”\",\"\\n\",\"^你站在门外，看着那道门缝里透出的光，冷气裹着你的手背。墓道深处，仿佛有什么东西在等着。\",\"\\n\",\"^你迈步跨过门槛，身后传来贾贵压低的嘀咕：“这灯，亮得可不太对劲。”\",\"\\n\",\"^尸灯的光在你前方晃了晃，像是被风扰动，又像是自己动了一下。\",\"\\n\",\"ev\",\"str\",\"^先察看墓门上的蛊纹\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},\"ev\",\"str\",\"^相信乔家承诺，随乔无咎开门\",\"/str\",\"/ev\",{\"*\":\".^.c-1\",\"flg\":4},\"ev\",\"str\",\"^不理会众人，独自先行勘探\",\"/str\",\"/ev\",{\"*\":\".^.c-2\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:read\",\"/#\",\"\\n\",{\"->\":\"bloodDoor\"},null],\"c-1\":[\"^ \",\"#\",\"^choice:qiao\",\"/#\",\"\\n\",{\"->\":\"bloodDoor\"},null],\"c-2\":[\"^ \",\"#\",\"^choice:alone\",\"/#\",\"\\n\",{\"->\":\"bloodDoor\"},null]}],null],\"bloodDoor\":[[\"^五道血锁各有一枚凹槽。乔无咎分配位置时没有看图纸，连哪一环最沉、哪一环先松都说得分明；他察觉到目光，才淡淡补了一句“乔家祖上留下过零星记载”。\",\"\\n\",\"^沈青萝放出青藤蛊，根须沿石缝攀住锁链。贾贵缩在金壳蛊后，仍不忘笑着让众人多担待。赵黎只伸两指在最难的一环上轻轻一按，锁内便传来骨裂似的闷响；他随即收手，仿佛只是恰巧碰对了地方。\",\"\\n\",\"^血锁断开时，门缝里涌出的不是尘土，而是一阵温热腥风。墓道深处的尸油灯一盏盏亮起，披甲的尸影在灯下缓缓抬头。\",\"\\n\",\"ev\",\"str\",\"^记下赵黎未曾掩饰的实力\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},\"ev\",\"str\",\"^跟紧沈青萝，护住她的侧翼\",\"/str\",\"/ev\",{\"*\":\".^.c-1\",\"flg\":4},\"ev\",\"str\",\"^催促众人冲过墓道\",\"/str\",\"/ev\",{\"*\":\".^.c-2\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:expose\",\"/#\",\"\\n\",{\"->\":\"corpseFight\"},null],\"c-1\":[\"^ \",\"#\",\"^choice:follow\",\"/#\",\"\\n\",{\"->\":\"corpseFight\"},null],\"c-2\":[\"^ \",\"#\",\"^choice:rush\",\"/#\",\"\\n\",{\"->\":\"corpseFight\"},null]}],null],\"corpseFight\":[\"^尸灯傀儡在墓道深处抬起头，甲片摩擦声贴着砖缝游走。尸油灯的火焰被它胸甲里的风吸得一缩，墓道里只剩铁靴拖地的细响。沈青萝的藤影伏在砖缝中，贾贵把金壳蛊顶在前方，赵黎却仍站在灯照不到的地方，袖口没有半点动静。\",\"\\n\",\"^傀儡忽然伏低身子，甲片一层层收紧。你看见它腰间挂着的灯芯由黄转白，便知这东西并不只是守门的死物。墓道太窄，任何一人退开，后面的人都会被它逼入墙角。轮到你出手。\",\"\\n\",\"end\",null],\"well\":[[\"^尸灯熄灭后，墓道尽头露出一口枯井。井沿刻满被指甲刮出的细痕，里面传来孩童断续的哭声：“师姐，别丢下我。”沈青萝的脸色在灯下白得厉害；她师弟沈砚三年前入荒原采药，此后便再无消息。\",\"\\n\",\"^每当哭声响起，井壁的薄霜便裂开一线，缝里渗出细密的血露。贾贵向后挪了半步，嘴上说应当从长计议，手却早已摸到药箱暗扣。赵黎笑称自己可替诸位试毒，脚尖却始终没有越过井口。\",\"\\n\",\"ev\",\"str\",\"^以真元护住沈青萝，下井查看\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},\"ev\",\"str\",\"^指出这是引魂蛊，强行离开\",\"/str\",\"/ev\",{\"*\":\".^.c-1\",\"flg\":4},\"ev\",\"str\",\"^顺势请赵黎先探井口\",\"/str\",\"/ev\",{\"*\":\".^.c-2\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:save\",\"/#\",\"\\n\",{\"->\":\"shell\"},null],\"c-1\":[\"^ \",\"#\",\"^choice:break\",\"/#\",\"\\n\",{\"->\":\"bloodTrap\"},null],\"c-2\":[\"^ \",\"#\",\"^choice:zhao-test\",\"/#\",\"\\n\",{\"->\":\"bloodTrap\"},null]}],null],\"shell\":[[\"^井下的石阶潮湿得像刚从血水里捞出。尽头没有沈砚，只有一具披着旧衣的空壳靠在井壁上；它听见脚步，空洞的胸腔里竟传出一声极轻的笑，随后吐出一枚黑牙蛊，连同衣物一起散作灰烬。\",\"\\n\",\"^灰烬间压着半枚玉牌，井壁缝里还塞有一张染血乔家符纸。沈青萝把玉牌扣在掌心，许久没有说话。她没有落泪，只把剑穗重新系紧，声音低得像从井底传来：“乔家若早知此处有引魂蛊，便不该再拿活人来填。”\",\"\\n\",\"^井口上方传来石盖挪动的闷响。有人正替你们关上退路。\",\"\\n\",\"ev\",\"str\",\"^留下玉牌与黑牙蛊作证\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},\"ev\",\"str\",\"^焚掉空壳，不让它再骗人\",\"/str\",\"/ev\",{\"*\":\".^.c-1\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:keep\",\"/#\",\"\\n\",{\"->\":\"bloodTrap\"},null],\"c-1\":[\"^ \",\"#\",\"^choice:burn\",\"/#\",\"\\n\",{\"->\":\"bloodTrap\"},null]}],null],\"bloodTrap\":[\"^众人离开枯井，乔无咎便不见了。墓壁随即翻转，数不清的针孔在砖缝间张开；第一阵血针擦过灯影，钉入地面时仍在微微震颤。乔无咎留在地上的半截灯芯没有熄，火头反而向机关深处弯去，像替主人指路。\",\"\\n\",\"^贾贵撑起金壳蛊，壳面立刻嵌满血针。沈青萝的藤蛊在半空截断针雨，断藤落下时带着焦黑腥气。赵黎终于收起笑容，望着前方暗道，像是认出了某种并不该出现在四转墓穴里的布置。\",\"\\n\",\"^墙砖每响三次，便有新一轮血针自更近处射来。你们必须击破这座机关，或者成为被它赶进深处的祭物。\",\"\\n\",\"end\",null],\"bloodHall\":[[\"^机关尽头是一座血色石室。石台玉匣中封着一只沉睡的五转蛊，背甲上血纹如同凝住的河流。乔家秘卷只称它为血流蛊，记载寥寥，仿佛连乔家人也不愿多谈它究竟能做什么。\",\"\\n\",\"^玉匣周围没有锁，只有五道干涸血槽。你们的影子落进去时，槽底的旧血竟一点点泛起光。贾贵的笑意彻底没了，沈青萝盯着匣面不动，赵黎却再也藏不住目中的贪婪。\",\"\\n\",\"^四壁同时响起乔无咎的声音。他承认自己已探明墓穴七分，邀众人入墓并非看中谁的本事，而是要以四人的血气加上乔家血脉，唤醒这只早已死去的五转蛊。\",\"\\n\",\"ev\",\"str\",\"^把真相摊开，与沈青萝、贾贵破阵\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},\"ev\",\"str\",\"^趁乱夺取血流蛊\",\"/str\",\"/ev\",{\"*\":\".^.c-1\",\"flg\":4},\"ev\",\"str\",\"^放弃玉匣，先追乔无咎\",\"/str\",\"/ev\",{\"*\":\".^.c-2\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:truth\",\"/#\",\"\\n\",{\"->\":\"lastGate\"},null],\"c-1\":[\"^ \",\"#\",\"^choice:seize\",\"/#\",\"\\n\",{\"->\":\"zhaoDuel\"},null],\"c-2\":[\"^ \",\"#\",\"^choice:chase\",\"/#\",\"\\n\",{\"->\":\"lastGate\"},null]}],null],\"zhaoDuel\":[\"^赵黎终于不再掩饰。寿蛊与血刃蛊自他袖中浮起，浑厚气息压得石室裂纹蔓延；先前那些勉强闪避、故作疲态，此刻都成了一场耐心极好的戏。他年轻的脸仍带着笑，眼神却老得像一口枯井。\",\"\\n\",\"^他抬手抹去额角伪装出的细纹，血线便沿手腕爬向玉匣。沉睡的血流蛊在匣中轻震，仿佛已经嗅到熟悉的血气。“小辈，把东西留下。”赵黎道，“老夫留你一条命。”\",\"\\n\",\"^他说得平静，石室的出口却已被血线封住。此处没有门派规矩，也没有乔家仆从，能活着握住玉匣的人，才有资格谈条件。\",\"\\n\",\"end\",null],\"zhaoDeath\":[[\"^血刃穿过护体真元时，疼痛并未立刻传来。你先听见自己血液涌出的细响，继而看见赵黎接住玉匣，神情像接回一件失落多年的旧物。远处传来乔无咎暴怒的喝声，赵黎却连头也没有回。\",\"\\n\",\"^“老夫原想留你一命。”他俯身说道，“可这只蛊不喜欢旁人替它做主。”玉匣裂开一道缝，暗红光芒贴上你的伤口。血流蛊初醒时，第一口吞掉的便是你最后一点生机。\",\"\\n\",\"ev\",\"str\",\"^在蛊墓中失去最后一丝意识\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:die\",\"/#\",\"\\n\",\"end\",null]}],null],\"lastGate\":[[\"^出口祭台前，乔无咎终于亲自现身。他衣袍上没有半点尘土，仿佛从一开始便不是入墓寻宝，而是来赴一场准备多年的仪式。祭台上的血线向四方蔓延，连尸灯、血针与暗道都被连成一张巨网。\",\"\\n\",\"^乔无咎承认乔家许诺只是饵料。只要血祭再亮一次，死者与伤者都会成为阵中一部分。贾贵不再提分宝，沈青萝也不再追问师弟；所有人都知道，活着离开不是靠运气，而是要从乔无咎手里硬抢。\",\"\\n\",\"ev\",\"str\",\"^踏破残阵，带人离开蛊墓\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},\"ev\",\"str\",\"^以自身真元强断血祭\",\"/str\",\"/ev\",{\"*\":\".^.c-1\",\"flg\":4},\"ev\",\"str\",\"^催动血流蛊，杀穿乔家血卫\",\"/str\",\"/ev\",{\"*\":\".^.c-2\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:leave\",\"/#\",\"\\n\",\"end\",null],\"c-1\":[\"^ \",\"#\",\"^choice:break\",\"/#\",\"\\n\",\"end\",null],\"c-2\":[\"^ \",\"#\",\"^choice:bloodflow\",\"/#\",\"\\n\",{\"->\":\"bloodRage\"},null]}],null],\"bloodRage\":[\"^血流蛊入体的瞬间，石室内每一滴血都像在你耳边奔流。乔无咎唤出最后的血卫，甲胄沉重，刀锋上的暗红却没有滴下，反而逆着空气向你掌心汇去。\",\"\\n\",\"^乔无咎第一次变了脸色。他以为自己复活的是乔家能够驾驭的遗蛊，却不知血流蛊既已认主，便再不听祭主号令。力量不断从伤口回涌，也不断催促你再向前一步。\",\"\\n\",\"^血卫举刀，祭台上的血线随之亮起。你能感觉到体内那条无形血河已冲到堤岸，下一击过后，留下的是乔无咎，还是你自己，谁也说不准。\",\"\\n\",\"end\",null],\"bloodExit\":[[\"^血卫在赤流中碎裂，祭台随之崩塌。乔无咎的怒喝被落石吞没，你踏过出口时，荒原冷风扑在脸上，竟让人一时分不清方才墓中的血腥是否只是幻觉。\",\"\\n\",\"^乔家车驾早已空了，仆从留下的车辙也被风抹平。你回头时，墓门已合成一块寻常石碑，将同伴、阴谋与未问出口的话一并埋回冻土。\",\"\\n\",\"^只有心口的血流蛊仍在轻轻蠕动。它替你记得每一滴血的去处，也像在提醒你：五转之力从来不会白白交到谁手中。\",\"\\n\",\"ev\",\"str\",\"^踏出蛊墓，任由血流蛊随心跳苏醒\",\"/str\",\"/ev\",{\"*\":\".^.c-0\",\"flg\":4},{\"c-0\":[\"^ \",\"#\",\"^choice:leave-blood\",\"/#\",\"\\n\",\"end\",null]}],null],\"ending_trapped\":[\"^尸灯灭时，活人也成了墓的一部分。\",\"\\n\",\"^你们在机关与迟疑中耗尽了最后的时机。血祭重新闭合，墓门外传来陌生脚步；乔家不会为几名散修的失踪停下，也仍会寻找下一批愿意入墓的四转蛊修。\",\"\\n\",\"end\",null],\"ending_bloodflow\":[\"^一蛊入心，血流如河。\",\"\\n\",\"^你夺得血流蛊，反杀乔家血卫，带着满身血腥走出荒原。它替你补回每一滴流失的生命，也在心底留下永不满足的饥渴；自此以后，究竟是你驾驭此蛊，还是此蛊借你行走，已无人能断言。\",\"\\n\",\"end\",null],\"ending_together\":[\"^有些债，活着才能偿。\",\"\\n\",\"^你与沈青萝凭玉牌拆解引魂血印，贾贵替你们挡住最后一轮机关。石门崩塌前，沈青萝望着荒原尽头，只说乔家的账要留到出去以后再算。\",\"\\n\",\"end\",null],\"ending_death\":[\"^血流蛊醒来时，第一个被吞掉的是你。\",\"\\n\",\"^赵黎夺走血流蛊，以你的血气完成它的初醒。墓门在身后合拢，乔家的阴谋、邪修的笑声与未查明的真相，都被留在了没有灯火的黑暗里。\",\"\\n\",\"end\",null],\"ending_alone\":[\"^活下来的人，也要背着秘密。\",\"\\n\",\"^你踏过最后一道血线，身后蛊墓再无声息。乔家的阴谋没能吞掉你，可荒原很大，追问真相的人也不会少；活下来并不意味着债已还清。\",\"\\n\",\"end\",null]}],\"listDefs\":{}}";
export default story;
